function perfectpixel_hide_posts_menu() {
	remove_menu_page( 'edit.php' );
}

function perfectpixel_hide_posts_screens() {
	global $pagenow;
	if ( wp_doing_ajax() || ! in_array( $pagenow, array( 'edit.php', 'post-new.php', 'edit-tags.php' ), true ) ) {
		return;
	}
	$post_type = isset( $_GET['post_type'] ) ? sanitize_key( wp_unslash( $_GET['post_type'] ) ) : 'post';
	$taxonomy  = isset( $_GET['taxonomy'] ) ? sanitize_key( wp_unslash( $_GET['taxonomy'] ) ) : '';
	if ( 'edit-tags.php' === $pagenow ? in_array( $taxonomy, array( 'category', 'post_tag' ), true ) && 'post' === $post_type : 'post' === $post_type ) {
		wp_safe_redirect( admin_url() );
		exit;
	}
}

function perfectpixel_hide_posts_admin_bar( $wp_admin_bar ) {
	$wp_admin_bar->remove_node( 'new-post' );
}

function perfectpixel_hide_posts_dashboard() {
	remove_meta_box( 'dashboard_quick_press', 'dashboard', 'side' );
}
